## res://comun/viz/primitivas.gd (PC y Vita): mallas solo de triángulos (H1), compartidas (H2), movidas por transform.
static var _cache := {}

static func material(c: Color) -> StandardMaterial3D:
	if not _cache.has(c):
		var m := StandardMaterial3D.new()
		m.albedo_color = Color(c, 0.99)                 # a <= 0,99: fuera de la pasada de luz en la Vita (H8)
		m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
		_cache[c] = m
	return _cache[c]

static func flecha(c: Color, n := 6) -> MeshInstance3D:   # unidad sobre -Z de Godot = +X de ROS
	if not _cache.has("flecha"):
		var st := SurfaceTool.new(); st.begin(Mesh.PRIMITIVE_TRIANGLES)
		for i in n:
			var a := Vector2.from_angle(TAU * i / n); var b := Vector2.from_angle(TAU * (i + 1) / n)
			for k in [[0.0, 0.75, 0.04, 0.04], [0.75, 1.0, 0.1, 0.0]]:   # asta y punta: z0, z1, r0, r1
				var p0 := Vector3(a.x * k[2], a.y * k[2], -k[0]); var p1 := Vector3(b.x * k[2], b.y * k[2], -k[0])
				var q0 := Vector3(a.x * k[3], a.y * k[3], -k[1]); var q1 := Vector3(b.x * k[3], b.y * k[3], -k[1])
				for v in [p0, q0, p1, p1, q0, q1]: st.add_vertex(v)
		_cache["flecha"] = st.commit()
	var mi := MeshInstance3D.new(); mi.mesh = _cache["flecha"]; mi.material_override = material(c)
	return mi

static func flecha_hacia(v: Vector3) -> Transform3D:
	var arriba := Vector3.UP if absf(v.normalized().y) < 0.99 else Vector3.RIGHT
	return Transform3D(Basis.looking_at(v, arriba).scaled_local(Vector3(1, 1, v.length())), Vector3.ZERO)

static func pose_godot(p) -> Transform3D:                 # geometry_msgs/Pose (RosMsg) -> Transform3D Godot
	var o = p.orientation; var x = p.position
	var q := Quaternion(o.x, o.y, o.z, o.w)
	q = q.normalized() if q.length_squared() > 1e-6 else Quaternion.IDENTITY
	return Transform3D(Basis(rclgd.ros_to_godot_quat(q)), rclgd.ros_to_godot_vector(Vector3(x.x, x.y, x.z)))

## header.frame_id -> marco fijo; null si TF no lo resuelve (RViz: «No transform from [x] to [fijo]»).
static func en_marco_fijo(tf, fijo: String, header) -> Variant:
	var f: String = header.frame_id.trim_prefix("/")
	if tf == null or f == "" or f == fijo: return Transform3D.IDENTITY
	return tf.lookup_transform(fijo, f, header.stamp)

extends Node3D
## Display PointStamped (RViz: esfera + History Length).
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/clicked_point"
@export var marco_fijo := "map"
@export var radio := 0.1
@export var historial := 10
@export var color := Color(1.0, 0.0, 1.0)
var tf
var sub: RosSubscriber
var _pool: Array[MeshInstance3D] = []
var _i := 0

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/PointStamped", _on_punto)
	for k in historial:
		var e := MeshInstance3D.new()
		e.mesh = Prim.esfera(); e.material_override = Prim.material(color); e.visible = false
		add_child(e); _pool.append(e)

func _on_punto(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var p = m.point
	var e := _pool[_i]; _i = (_i + 1) % historial
	e.transform = Transform3D(Basis.from_scale(Vector3.ONE * radio), fijo * rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
	e.visible = true

extends Node3D
