## Display Pose (PoseStamped) como RViz: flecha o ejes en el marco fijo.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/goal_pose"
@export var marco_fijo := "map"
@export_enum("flecha", "ejes") var forma := "flecha"
@export var largo := 1.0                  # RViz: Shaft Length 1 + Head Length 0.3
@export var color := Color(1.0, 0.1, 0.0)
var tf
var sub: RosSubscriber
var _vis: MeshInstance3D

func configurar(nodo: RosNode, listener, qos: RosQoS = null) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/PoseStamped", _on_pose, qos)
	_vis = Prim.flecha(color) if forma == "flecha" else Prim.ejes()
	_vis.visible = false
	add_child(_vis)

func _on_pose(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null:
		_vis.visible = false
		return
	_vis.transform = (fijo * Prim.pose_godot(m.pose)).scaled_local(Vector3.ONE * largo)
	_vis.visible = true

