## Display PoseArray: pool de flechas (PC) reutilizado; las sobrantes se ocultan.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/poses"
@export var marco_fijo := "map"
@export var largo := 0.3
@export var maximo := 200               # Vita: <= 40 (H2: un draw por instancia)
@export var color := Color(1.0, 0.1, 0.0)
var tf
var sub: RosSubscriber
var _pool: Array[MeshInstance3D] = []

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/PoseArray", _on_poses)

func _on_poses(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var poses: Array = m.poses
	var n := mini(poses.size(), maximo)
	while _pool.size() < n:
		var f := Prim.flecha(color); add_child(f); _pool.append(f)
	for i in _pool.size():
		_pool[i].visible = i < n
		if i < n:
			_pool[i].transform = (fijo * Prim.pose_godot(poses[i])).scaled_local(Vector3.ONE * largo)

