## PoseWithCovarianceStamped: flecha + elipse 2σ (caso 2D de RViz CovarianceVisual) + yaw.
const Prim = preload("res://comun/viz/primitivas.gd")
const C := Basis(Vector3(0, 0, -1), Vector3(-1, 0, 0), Vector3(0, 1, 0))   # ejes ROS en Godot (util_ros.gd)
@export var topic := "/amcl_pose"
@export var marco_fijo := "map"
@export var escala_pos := 1.0
var tf
var sub: RosSubscriber
var _flecha: MeshInstance3D
var _elipse: MeshInstance3D       # disco unidad en el plano XY de ROS (abanico de 12 tri)

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/PoseWithCovarianceStamped", _on_msg)
	_flecha = Prim.flecha(Color(1, 0.1, 0)); _elipse = Prim.disco(Color(1, 0.4, 1))
	add_child(_flecha); add_child(_elipse)

func _on_msg(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var t: Transform3D = fijo * Prim.pose_godot(m.pose.pose)
	_flecha.transform = t
	var c: PackedFloat64Array = m.pose.covariance
	var a := c[0]; var b := c[1]; var d := c[7]
	var h := sqrt(((a - d) * 0.5) ** 2 + b * b)
	var l1 := maxf((a + d) * 0.5 + h, 0.0); var l2 := maxf((a + d) * 0.5 - h, 0.0)
	var th := 0.5 * atan2(2.0 * b, a - d)               # eje mayor en el plano XY de ROS
	var z := 0.002 if (c[14] <= 0.0 and c[21] <= 0.0 and c[28] <= 0.0) else 2.0 * sqrt(maxf(c[14], 0.0))
	var b_ros := Basis(Vector3(0, 0, 1), th).scaled_local(Vector3(2.0 * sqrt(l1), 2.0 * sqrt(l2), z) * escala_pos)
	_elipse.transform = Transform3D(fijo.basis * C * b_ros * C.transposed(), t.origin)
	_elipse.visible = l1 > 0.0

extends Node3D
## Display «screw» de RViz (TwistStamped/AccelStamped/WrenchStamped): flecha lineal y angular + anillo.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var tipo := "geometry_msgs/msg/TwistStamped"     # o AccelStamped / WrenchStamped
@export var topic := "/cmd_vel_stamped"
@export var marco_fijo := "base_link"
@export var escala_lineal := 1.0                          # RViz Wrench: Force Arrow Scale 2
@export var escala_angular := 1.0
@export var ocultar_pequenos := true                      # RViz: Hide Small Values
var tf
var sub: RosSubscriber
var _lin: MeshInstance3D
var _ang: MeshInstance3D
var _anillo: MeshInstance3D

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, tipo, _on_msg)
	_lin = Prim.flecha(Color(0.8, 0.2, 0.2)); _ang = Prim.flecha(Color(0.8, 0.8, 0.2))
	_anillo = Prim.anillo(Color(0.8, 0.8, 0.2))         # arco de 315° en XY, radio 1 (wrench_visual.cpp)
	for n in [_lin, _ang, _anillo]: add_child(n)

func _on_msg(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var es_w := tipo.ends_with("WrenchStamped")
	var c = m.get_member("wrench" if es_w else ("twist" if tipo.ends_with("TwistStamped") else "accel"))
	var a = c.get_member("force" if es_w else "linear"); var b = c.get_member("torque" if es_w else "angular")
	var vl := rclgd.ros_to_godot_vector(Vector3(a.x, a.y, a.z)) * escala_lineal
	var va := rclgd.ros_to_godot_vector(Vector3(b.x, b.y, b.z)) * escala_angular
	var umbral := 0.01 if ocultar_pequenos else 1e-6
	_lin.visible = vl.length() > umbral
	_ang.visible = va.length() > umbral
	_anillo.visible = _ang.visible
	if _lin.visible: _lin.transform = fijo * Prim.flecha_hacia(vl)
	if _ang.visible:
		var t: Transform3D = fijo * Prim.flecha_hacia(va)
		_ang.transform = t
		var r := va.length() * 0.25                        # anillo de radio L/4 a mitad del eje
		_anillo.transform = t.translated_local(Vector3(0, 0, -0.5)).scaled_local(Vector3(r, r, 1.0 / va.length()))

extends Node3D
