## QuaternionStamped -> ejes RGB girados + RPY en el HUD.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/orientacion"
@export var marco_fijo := "base_link"
@export var largo := 0.5
var tf
var sub: RosSubscriber
var _ejes: MeshInstance3D
var rpy_grados := Vector3.ZERO          # para el HUD

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/QuaternionStamped", _on_q)
	_ejes = Prim.ejes(); add_child(_ejes)

func _on_q(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var o = m.quaternion
	var q := Quaternion(o.x, o.y, o.z, o.w)
	if q.length_squared() < 1e-6: return
	q = q.normalized()
	_ejes.transform = (fijo * Transform3D(Basis(rclgd.ros_to_godot_quat(q)), Vector3.ZERO)).scaled_local(Vector3.ONE * largo)
	rpy_grados = Vector3(atan2(2.0 * (q.w * q.x + q.y * q.z), 1.0 - 2.0 * (q.x * q.x + q.y * q.y)),
			asin(clampf(2.0 * (q.w * q.y - q.z * q.x), -1.0, 1.0)),
			atan2(2.0 * (q.w * q.z + q.x * q.y), 1.0 - 2.0 * (q.y * q.y + q.z * q.z))) * (180.0 / PI)

