## TransformStamped suelto -> ejes del hijo + flecha hijo->padre (como un frame del TF display).
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/transform"
@export var marco_fijo := "map"
var tf
var sub: RosSubscriber
var _ejes: MeshInstance3D
var _enlace: MeshInstance3D
var nombre_hijo := ""                    # etiqueta 2D (Camera3D.unproject_position)

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/TransformStamped", _on_t)
	_ejes = Prim.ejes(); _enlace = Prim.flecha(Color(1.0, 0.9, 0.2))
	add_child(_ejes); add_child(_enlace)

func _on_t(m: RosMsg) -> void:
	var padre = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if padre == null: return
	var r = m.transform.rotation; var p = m.transform.translation
	var q := Quaternion(r.x, r.y, r.z, r.w).normalized()
	var hijo: Transform3D = padre * Transform3D(Basis(rclgd.ros_to_godot_quat(q)), rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
	_ejes.transform = hijo.scaled_local(Vector3.ONE * 0.3)
	nombre_hijo = m.child_frame_id
	var v: Vector3 = padre.origin - hijo.origin
	_enlace.visible = v.length() > 1e-3
	if _enlace.visible: _enlace.transform = Transform3D(Prim.flecha_hacia(v).basis, hijo.origin)

