## PolygonStamped -> contorno cerrado como cinta (2 tri/segmento; válida en la Vita, H1).
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/local_costmap/published_footprint"
@export var marco_fijo := "odom"
@export var ancho := 0.02
var tf
var sub: RosSubscriber
var _malla := ArrayMesh.new()
var _anterior := PackedVector3Array()

func configurar(nodo: RosNode, listener) -> void:
	tf = listener; mesh = _malla; material_override = Prim.material(Color(0.2, 0.9, 0.3))
	sub = nodo.create_subscription(topic, "geometry_msgs/msg/PolygonStamped", _on_poly)

func _on_poly(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	transform = fijo                                     # el marco va en el nodo: la malla solo cambia si cambia la forma
	var pts := PackedVector3Array()
	for p in m.polygon.points: pts.append(rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
	if pts == _anterior or pts.size() < 2: return
	_anterior = pts
	_malla.clear_surfaces()
	var st := SurfaceTool.new(); st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for i in pts.size():
		var a := pts[i]; var b := pts[(i + 1) % pts.size()]
		var lado := (b - a).cross(Vector3.UP).normalized() * ancho * 0.5
		for v in [a - lado, a + lado, b - lado, b - lado, a + lado, b + lado]: st.add_vertex(v)
	st.commit(_malla)

