## InertiaStamped -> caja de inercia equivalente (densidad uniforme) en el CoM, ejes principales por Jacobi.
const Prim = preload("res://comun/viz/primitivas.gd")
const C := Basis(Vector3(0, 0, -1), Vector3(-1, 0, 0), Vector3(0, 1, 0))
var tf
var marco_fijo := "base_link"
var _caja: MeshInstance3D

func _on_inercia(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	var i = m.inertia
	if fijo == null or i.m <= 0.0: return
	var a := [[i.ixx, i.ixy, i.ixz], [i.ixy, i.iyy, i.iyz], [i.ixz, i.iyz, i.izz]]
	var v := Basis()                                       # columnas = autovectores (ejes ROS)
	for barrido in 10:                                     # Jacobi cíclico 3x3
		for pq in [[0, 1], [0, 2], [1, 2]]:
			var p: int = pq[0]; var q: int = pq[1]
			if absf(a[p][q]) < 1e-12: continue
			var th := 0.5 * atan2(2.0 * a[p][q], a[q][q] - a[p][p])
			var c := cos(th); var s := sin(th)
			for k in 3:                                    # A <- A·J
				var akp: float = a[k][p]; var akq: float = a[k][q]
				a[k][p] = c * akp - s * akq; a[k][q] = s * akp + c * akq
			for k in 3:                                    # A <- Jᵀ·A
				var apk: float = a[p][k]; var aqk: float = a[q][k]
				a[p][k] = c * apk - s * aqk; a[q][k] = s * apk + c * aqk
			var vp := v[p]; var vq := v[q]
			v[p] = c * vp - s * vq; v[q] = s * vp + c * vq
	var l := Vector3(a[0][0], a[1][1], a[2][2])
	var lados := Vector3(l.y + l.z - l.x, l.x + l.z - l.y, l.x + l.y - l.z) * (6.0 / i.m)
	lados = Vector3(sqrt(maxf(lados.x, 0.0)), sqrt(maxf(lados.y, 0.0)), sqrt(maxf(lados.z, 0.0)))
	var com := rclgd.ros_to_godot_vector(Vector3(i.com.x, i.com.y, i.com.z))
	_caja.transform = fijo * Transform3D(C * v.scaled_local(lados) * C.transposed(), com)

