## Display Odometry como RViz: flecha nueva solo si se mueve > tolerancia; pool circular de `keep`.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/odom"
@export var marco_fijo := "odom"
@export var tol_pos := 0.1                 # m (RViz Position Tolerance)
@export var tol_ang := 0.1                 # rad (RViz Angle Tolerance)
@export var keep := 100                    # Vita: <= 20 (doc 31, tabla §3)
@export var color := Color(1.0, 0.1, 0.0)
var tf
var sub: RosSubscriber
var _pool: Array[MeshInstance3D] = []
var _sig := 0
var _ultima: Variant = null                # Transform3D de la última flecha dibujada

func configurar(nodo: RosNode, listener, qos: RosQoS = null) -> void:
	tf = listener
	sub = nodo.create_subscription(topic, "nav_msgs/msg/Odometry", _on_odom, qos)
	for i in keep:
		var f := Prim.flecha(color); f.visible = false; add_child(f); _pool.append(f)

func _on_odom(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var t: Transform3D = fijo * Prim.pose_godot(m.pose.pose)
	if _ultima != null:
		var u: Transform3D = _ultima
		if t.origin.distance_to(u.origin) < tol_pos and \
				t.basis.get_rotation_quaternion().angle_to(u.basis.get_rotation_quaternion()) < tol_ang:
			return
	_ultima = t
	var f := _pool[_sig]
	_sig = (_sig + 1) % keep
	f.transform = t
	f.visible = true

extends MeshInstance3D
## Display Path: cinta (2 tri/segmento) en PC y Vita (H1: sin líneas 3D). Dos entradas: Path o path_compacto.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var marco_fijo := "map"
@export var ancho := 0.03                  # RViz Line Width
@export var color := Color(0.1, 1.0, 0.0)
var tf
var _malla := ArrayMesh.new()

func _ready() -> void:
	mesh = _malla
	material_override = Prim.material(color)

func on_path(m: RosMsg) -> void:           # nav_msgs/msg/Path (PC)
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	transform = fijo                        # un lookup por mensaje, como RViz
	var pts := PackedVector3Array()
	for ps in m.poses:
		var p = ps.pose.position
		pts.append(rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
	_construir(pts)

func on_path_compacto(m: RosMsg) -> void:  # Vita: /vita/path_compacto [n, x0, y0, ...] en `map`, 2 Hz
	var d: PackedFloat32Array = m.data
	var pts := PackedVector3Array()
	for i in mini(int(d[0]) if d.size() > 0 else 0, (d.size() - 1) / 2):
		pts.append(rclgd.ros_to_godot_vector(Vector3(d[1 + 2 * i], d[2 + 2 * i], 0.02)))
	_construir(pts)

func _construir(pts: PackedVector3Array) -> void:
	_malla.clear_surfaces()
	if pts.size() < 2: return
	var st := SurfaceTool.new(); st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for i in pts.size() - 1:
		var a := pts[i]; var b := pts[i + 1]
		var lado := (b - a).cross(Vector3.UP).normalized() * ancho * 0.5
		for v in [a - lado, a + lado, b - lado, b - lado, a + lado, b + lado]: st.add_vertex(v)
	st.commit(_malla)

