## Display TF: ejes por frame + flecha hijo->padre, a 10 Hz, desde un listener (RosTfListener o TfLigero).
const Prim = preload("res://comun/viz/primitivas.gd")
@export var marco_fijo := "map"
@export var escala := 0.3                  # RViz Marker Scale
@export var timeout_s := 15.0              # RViz Frame Timeout
@export var periodo := 0.1
var tf
var nodo: RosNode
var _ejes := {}                            # frame -> MeshInstance3D
var _flechas := {}                         # frame -> MeshInstance3D (hijo -> padre)
var posiciones := {}                       # frame -> Vector3, para los nombres 2D
var _t := 0.0

func _process(dt: float) -> void:
	_t += dt
	if tf == null or _t < periodo: return
	_t = 0.0
	var st = nodo.now()
	var ahora: float = st.sec + st.nanosec * 1e-9
	for f in tf.get_frame_names():
		if not _ejes.has(f):
			_ejes[f] = Prim.ejes(); _flechas[f] = Prim.flecha(Color(1, 0.9, 0.2))
			add_child(_ejes[f]); add_child(_flechas[f])
		var t = tf.lookup_transform(marco_fijo, f)
		var ultimo: float = tf.get_frame_latest_time(f)
		var vivo: bool = t != null and (ultimo == 0.0 or ahora - ultimo < timeout_s)
		_ejes[f].visible = vivo
		_flechas[f].visible = false
		if not vivo: continue
		_ejes[f].transform = t.scaled_local(Vector3.ONE * escala)
		posiciones[f] = t.origin
		var padre: String = tf.get_frame_parent(f)
		var tp = tf.lookup_transform(marco_fijo, padre) if padre != "" else null
		if tp != null and tp.origin.distance_to(t.origin) > 1e-3:
			_flechas[f].transform = Transform3D(Prim.flecha_hacia(tp.origin - t.origin).basis, t.origin)
			_flechas[f].visible = true

