## TfLigero: subconjunto de RosTfListener para la Vita (último valor por frame, `time` ignorado, como tf-tree).
var _padre := {}                          # hijo -> padre
var _local := {}                          # hijo -> Transform3D (Godot) del hijo en el padre
var _sello := {}                          # hijo -> s (0.0 = estático)
var _error := ""
var subs: Array[RosSubscriber] = []

func _init(nodo: RosNode, topic_tf := "/tf", topic_static := "/tf_static") -> void:
	var be := RosQoS.new(); be.set_reliability(RosQoS.BEST_EFFORT)
	var fijo := RosQoS.new(); fijo.set_reliability(RosQoS.RELIABLE); fijo.set_durability(RosQoS.TRANSIENT_LOCAL)
	subs = [nodo.create_subscription(topic_tf, "tf2_msgs/msg/TFMessage", _on_tf.bind(false), be),
			nodo.create_subscription(topic_static, "tf2_msgs/msg/TFMessage", _on_tf.bind(true), fijo)]

func _on_tf(m: RosMsg, estatico: bool) -> void:
	for ts in m.transforms:
		var hijo: String = ts.child_frame_id.trim_prefix("/")
		var r = ts.transform.rotation; var p = ts.transform.translation
		_padre[hijo] = ts.header.frame_id.trim_prefix("/")
		_local[hijo] = Transform3D(Basis(rclgd.ros_to_godot_quat(Quaternion(r.x, r.y, r.z, r.w).normalized())),
				rclgd.ros_to_godot_vector(Vector3(p.x, p.y, p.z)))
		_sello[hijo] = 0.0 if estatico else ts.header.stamp.sec + ts.header.stamp.nanosec * 1e-9

func _a_raiz(f: String) -> Array:         # [Transform3D de f en la raíz, nombre de la raíz]
	var t := Transform3D.IDENTITY
	for n in 32:                          # tope de modules/tf-tree; corta ciclos
		if _padre.has(f): t = _local[f] * t; f = _padre[f]
	return [t, f]

func lookup_transform(target: String, source: String, _time = null, _timeout := 0.0) -> Variant:
	var a := _a_raiz(source); var b := _a_raiz(target)
	if a[1] != b[1] or not (frame_exists(source) and frame_exists(target)):
		_error = "%s y %s no están conectados" % [target, source]; return null
	_error = ""; return (b[0] as Transform3D).affine_inverse() * a[0]

func frame_exists(f: String) -> bool: return _padre.has(f) or _padre.values().has(f)
func get_frame_names() -> PackedStringArray: return PackedStringArray(_padre.keys())
func get_frame_parent(f: String) -> String: return _padre.get(f, "")
func get_frame_latest_time(f: String) -> float: return _sello.get(f, 0.0)
func get_last_error() -> String: return _error

extends Node3D
