var sub: RosSubscriber
var _ejes: MeshInstance3D
var _acel: MeshInstance3D
var _giro: MeshInstance3D

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)   # los IMU publican en BE
	sub = nodo.create_subscription(topic, "sensor_msgs/msg/Imu", _on_imu, qos)
	_ejes = Prim.ejes(); _acel = Prim.flecha(Color(1, 0.8, 0)); _giro = Prim.flecha(Color(0, 0.8, 1))
	for n in [_ejes, _acel, _giro]: add_child(n)

func _on_imu(m: RosMsg) -> void:
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	if fijo == null: return
	var o = m.orientation
	_ejes.visible = m.orientation_covariance[0] != -1.0          # -1 = sin orientación (Imu.msg)
	if _ejes.visible:                                             # orientación absoluta en la posición del IMU
		var q := Quaternion(o.x, o.y, o.z, o.w).normalized()
		_ejes.transform = Transform3D(Basis(rclgd.ros_to_godot_quat(q)), fijo.origin)
	var a = m.linear_acceleration; var w = m.angular_velocity
	_poner(_acel, fijo, rclgd.ros_to_godot_vector(Vector3(a.x, a.y, a.z)) * escala_acel)
	_poner(_giro, fijo, rclgd.ros_to_godot_vector(Vector3(w.x, w.y, w.z)) * escala_giro)

func _poner(f: MeshInstance3D, fijo: Transform3D, v: Vector3) -> void:
	f.visible = v.length() > 1e-3
	if f.visible: f.transform = fijo * Prim.flecha_hacia(v)

