## NavSatFix -> rastro ENU local (planta 2D) + círculo 2σ coloreado por el estado del fix.
const R_TIERRA := 6378137.0
@export var topic := "/gps/fix"
@export var px_por_m := 4.0
@export var max_puntos := 300
var sub: RosSubscriber
var _lat0 := NAN                            # float de GDScript = 64 bits; NO usar Vector2 (float32)
var _lon0 := 0.0
var _rastro := PackedVector2Array()
var _sigma := 0.0
var _estado := -1

func configurar(nodo: RosNode) -> void:
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	sub = nodo.create_subscription(topic, "sensor_msgs/msg/NavSatFix", _on_fix, qos)

func _on_fix(m: RosMsg) -> void:
	_estado = m.status.status                              # -1 NO_FIX, 0 FIX, 1 SBAS, 2 GBAS
	if _estado < 0 or is_nan(m.latitude): return
	if is_nan(_lat0):
		_lat0 = m.latitude; _lon0 = m.longitude
	var este: float = deg_to_rad(m.longitude - _lon0) * R_TIERRA * cos(deg_to_rad(_lat0))
	var norte: float = deg_to_rad(m.latitude - _lat0) * R_TIERRA
	_rastro.append(Vector2(este, -norte) * px_por_m)       # pantalla: y hacia abajo
	if _rastro.size() > max_puntos: _rastro.remove_at(0)
	var c: PackedFloat64Array = m.position_covariance
	_sigma = sqrt(maxf(c[0], c[4])) if m.position_covariance_type > 0 else 0.0
	queue_redraw()

func _draw() -> void:
	if _rastro.size() >= 2: draw_polyline(_rastro, Color(0.2, 0.8, 1.0), 2.0)   # H17: un comando
	if _rastro.is_empty(): return
	var col := Color.RED if _estado < 0 else (Color.GREEN if _estado == 0 else Color.DODGER_BLUE)
	draw_arc(_rastro[-1], maxf(2.0 * _sigma * px_por_m, 3.0), 0.0, TAU, 24, col, 1.0)

