## Display Range como RViz: cono de largo r y ancho 2·r·tan(fov/2); fuera de rango -> oculto.
const Prim = preload("res://comun/viz/primitivas.gd")
@export var topic := "/range"
@export var marco_fijo := "base_link"
@export var color := Color(1, 1, 1)        # RViz: blanco, alfa 0,5 (en la Vita, opaco)
var tf
var sub: RosSubscriber
var _cono: MeshInstance3D                  # cono unidad: vértice en el origen, base en z = -1, radio 0,5

func configurar(nodo: RosNode, listener) -> void:
	tf = listener
	var qos := RosQoS.new(); qos.set_reliability(RosQoS.BEST_EFFORT)
	sub = nodo.create_subscription(topic, "sensor_msgs/msg/Range", _on_range, qos)
	_cono = Prim.cono(color); _cono.visible = false; add_child(_cono)

func _on_range(m: RosMsg) -> void:
	var r: float = m.range
	var mostrado := 0.0                                      # range_display.cpp getDisplayedRange
	if r >= m.min_range and r <= m.max_range:
		mostrado = r
	elif m.min_range == m.max_range and is_inf(r) and r < 0.0:
		mostrado = m.min_range
	var fijo = Prim.en_marco_fijo(tf, marco_fijo, m.header)
	_cono.visible = fijo != null and mostrado > 0.0
	if not _cono.visible: return
	var ancho := 2.0 * mostrado * tan(m.field_of_view * 0.5)
	_cono.transform = fijo * Transform3D(Basis.from_scale(Vector3(ancho, ancho, mostrado)), Vector3.ZERO)
